"""Combine actual source-scoped observations without promoting source maps to behavior proof."""
import json, subprocess
from datetime import datetime, timezone
from pathlib import Path
E=Path(__file__).resolve().parent;ROOT=E.parents[3]
read=lambda n:json.loads((E/n).read_text(encoding='utf-8-sig'))
qa=read('qa-command-results.json')
final_ids={r['id'] for r in qa if r['id'].startswith('final-ready-') or r['id'] in ['post-table-default-68','table-key-old-contract-repeat','focused-old-studio-repeat','final-history-ready-repeat']}
ids=['route-content-sweep','final-cross-engine-all','post-safearea-cross-engine','final-combined-fixed','post-safearea-combined','default-concurrency','post-final-default-concurrency','baseline-phase02-unchanged','final-phase02-unchanged','final-special-modes','post-final-shell-probes','priority-pointer-renderers','interaction-profile','post-zero-shell-probes','post-zero-special-modes','post-zero-renderer-review','post-zero-interaction-profile','history-zero-recovery','history-zero-recovery-fixed','zero-history-early-seed-fixed']
result={'generatedAt':datetime.now(timezone.utc).isoformat(),'generatedAtSha':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'evidenceLevels':{'SOURCE-MAPPED':'Current factory/import/shell association only','FIXTURE VERIFIED':'Named browser behavior with fictional local DTOs','CROSS-ENGINE VERIFIED':'Named tests run in Chromium, WebKit, Firefox; not physical devices','DEVICE VERIFIED':'Not supplied in this execution'},'commands':[r for r in qa if r['id'] in ids],'shells':{stage:read(stage+'-shell-probes.json') for stage in ['before','after']},'specialModes':read('special-mode-results.json'),'nativeZoom':read('native-zoom-results.json'),'limits':['Every current route has an initial content observation at two sizes; no all-state or all-role certification','Axe/focus/child geometry checks are scoped to selected interactive surfaces','Native browser zoom, real phones, AT and OS scaling remain separate gates']}
result['commands']=[r for r in qa if r['id'] in set(ids)|final_ids]
(E/'responsive-focus-results.json').write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
environment={'generatedAt':result['generatedAt'],'nativeZoom':{'status':'BLOCKED — EXTERNAL','playwrightAttempt':'Headed Control+Equal left DPR unchanged; not accepted as native zoom','desktopBridgeAttempt':'Two get_window calls rejected the exact owned Chrome handle returned by sky as no longer owned, while reporting current owner Chrome','error':'window id 1640326 no longer belongs to Chrome; current owner is Chrome','actionTaken':'No native key injection after targeting failed; no window guesses'},'fontBinaryMetadata':{'status':'FIXTURE VERIFIED','reason':'Temporary ignored fontTools parser installed; binary metadata and license hashes retained in local-font-metadata.json. No application dependency or font asset changed'},'interruptedLab':{'status':'INTERRUPTED','archive':'output/playwright/uxui-phase06-2026-11-17/lab-first-interrupted-attempt.json','reason':'Before-only attempt interrupted across resumed session; wrong editor readiness selector corrected before fresh --restart run'},'correctedHarnessLimits':['Early PowerShell array metadata serialization was recovered from retained command logs; missing original durations not fabricated','NUL-delimited git paths now handle Khmer asset filenames','HTTP fixture routing moved to loopback server because Playwright page.route disables cache','Unknown sandbox origins skip test-only storage initialization','Wrong Studio readiness/action selectors corrected without changing original Phase 02 assertions']}
(E/'environment-limits.json').write_text(json.dumps(environment,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'shellObservations':len(result['shells']['after']['rows']),'commandEvidence':len(result['commands']),'specialModes':len(result['specialModes']['rows'])}))
